// BM6 -> ESP32-C3 com OLED 0.42" embutido (72x40, SSD1306, SDA=5 SCL=6)
// Mostra so a tensao e se esta conectado.
// Libs: NimBLE-Arduino 2.x, U8g2. Placa: ESP32C3 Dev Module (USB CDC On Boot: Enabled).

#include <Arduino.h>
#include <Wire.h>
#include <U8g2lib.h>
#include <NimBLEDevice.h>
#include "mbedtls/aes.h"
#include <Adafruit_SSD1306.h>
#include <os.h>

#define PIN_SDA 5
#define PIN_SCL 6

U8G2_SSD1306_72X40_ER_F_HW_I2C oled(U8G2_R0, U8X8_PIN_NONE);

static const uint8_t KEY[16] = {108, 101, 97, 103, 101, 110, 100, 255,
                                254, 48, 49, 48, 48, 48, 48, 57};

volatile float voltage = 0;
volatile uint32_t lastRx = 0;
volatile bool connected = false;

NimBLEClient* client = nullptr;
NimBLERemoteCharacteristic* chWrite = nullptr;

void aes(const uint8_t* in, uint8_t* out, bool enc) {
  mbedtls_aes_context ctx;
  mbedtls_aes_init(&ctx);
  if (enc) mbedtls_aes_setkey_enc(&ctx, KEY, 128);
  else     mbedtls_aes_setkey_dec(&ctx, KEY, 128);
  mbedtls_aes_crypt_ecb(&ctx, enc ? MBEDTLS_AES_ENCRYPT : MBEDTLS_AES_DECRYPT, in, out);
  mbedtls_aes_free(&ctx);
}

void onNotify(NimBLERemoteCharacteristic*, uint8_t* raw, size_t len, bool) {
  if (len != 16) return;
  uint8_t d[16];
  aes(raw, d, false);
  if (d[0] != 0xd1 || d[1] != 0x55 || d[2] != 0x07 || d[3] == 0xff) return;
  float v = ((d[7] << 8) | d[8]) / 100.0f;
  if (v == 0) return;
  voltage = v;
  lastRx = millis();
}

class ClientCB : public NimBLEClientCallbacks {
  void onDisconnect(NimBLEClient*, int) override {
    connected = false;
    chWrite = nullptr;
  }
} clientCB;

void draw(const char* msg) {
  char buf[12];
  oled.clearBuffer();
  if (voltage > 0) {
    oled.setFont(u8g2_font_logisoso16_tn);
    snprintf(buf, sizeof buf, "%.2f", (float)voltage);
    oled.drawStr(0, 20, buf);
    oled.setFont(u8g2_font_5x7_tr);
    oled.drawStr(oled.getDisplayWidth() - 6, 20, "V");
  }
  oled.setFont(u8g2_font_5x7_tr);
  oled.drawStr(0, 38, msg);
  oled.sendBuffer();
}

bool connectBM6() {
  draw("Procurando");
  NimBLEScan* scan = NimBLEDevice::getScan();
  scan->setActiveScan(true);
  NimBLEScanResults res = scan->getResults(5000, false);

  const NimBLEAdvertisedDevice* target = nullptr;
  for (int i = 0; i < res.getCount(); i++) {
    if (res.getDevice(i)->getName() == "BM6") { target = res.getDevice(i); break; }
  }
  if (!target) return false;

  draw("Conectando");
  if (!client) {
    client = NimBLEDevice::createClient();
    client->setClientCallbacks(&clientCB, false);
  }
  if (!client->connect(target)) return false;

  NimBLERemoteCharacteristic* chNotify = nullptr;
  for (auto* svc : client->getServices(true)) {
    for (auto* ch : svc->getCharacteristics(true)) {
      String u = ch->getUUID().toString().c_str();
      u.toLowerCase();
      if (u.indexOf("fff3") >= 0) chWrite = ch;
      if (u.indexOf("fff4") >= 0) chNotify = ch;
    }
  }
  if (!chWrite || !chNotify) { client->disconnect(); return false; }

  chNotify->subscribe(true, onNotify);
  uint8_t c[16] = {0xd1, 0x55, 0x07}, e[16];
  aes(c, e, true);
  chWrite->writeValue(e, 16, true);
  lastRx = millis();
  connected = true;
  return true;
}

void setup() {
  Serial.begin(115200);
  Wire.begin(PIN_SDA, PIN_SCL);
  oled.begin();
  oled.setContrast(255);
  draw("Iniciando");
  NimBLEDevice::init("");
}

void loop() {
  static uint32_t lastTry = 0;

  if (!connected && (lastTry == 0 || millis() - lastTry > 15000)) {
    lastTry = millis();
    connectBM6();
  }

  // Sem dado por 30 s: forca reconexao
  if (connected && millis() - lastRx > 30000) {
    lastRx = millis();
    client->disconnect();
  }

  draw(connected ? "Conectado" : "Desconect.");
  delay(500);
}
